  ('a1000000-0000-4000-8000-000000000001', 'Kaelith Vroun', '{"id":"a1000000-0000-4000-8000-000000000001","schemaVersion":4,"createdAt":"2026-01-01T00:00:00.000Z","updatedAt":"2026-01-01T00:00:00.000Z","identity":{"name":"Kaelith Vroun","player":"","className":"Wizard","subclass":"Evoker","level":3,"species":"Elf","background":"Sage","alignment":"Neutral","xp":0,"portrait":"assets/portraits/wizard.webp","accent":"#5b7fc4","tagline":"The library burns and he keeps reading"},"abilities":{"str":8,"dex":14,"con":13,"int":17,"wis":12,"cha":10},"saves":{"str":0,"dex":0,"con":0,"int":1,"wis":1,"cha":0},"skills":{"acrobatics":0,"animalHandling":0,"arcana":1,"athletics":0,"deception":0,"history":1,"insight":0,"intimidation":0,"investigation":1,"medicine":0,"nature":0,"perception":0,"performance":0,"persuasion":0,"religion":0,"sleightOfHand":0,"stealth":0,"survival":0},"combat":{"armorClass":12,"speed":30,"initiativeBonus":0,"hpMax":20,"hpCurrent":14,"hpTemp":0,"hitDieSize":6,"hitDiceTotal":3,"hitDiceSpent":0,"deathSuccesses":0,"deathFailures":0,"heroicInspiration":false,"exhaustion":0,"conditions":[],"attacks":[{"name":"Dagger","ability":"dex","proficient":true,"damage":"1d4","damageType":"Piercing","range":"Melee or 20/60 ft.","mastery":"Nick","notes":"","id":"kaelith-atk-1"},{"name":"Quarterstaff","ability":"str","proficient":true,"damage":"1d6","damageType":"Bludgeoning","range":"Melee","mastery":"Topple","notes":"Two-handed: 1d8.","id":"kaelith-atk-2"},{"name":"Ray of Frost","ability":"int","proficient":true,"damage":"1d8","damageType":"Cold","range":"60 feet","mastery":"—","notes":"Cantrip. The target''s Speed drops by 10 feet.","id":"kaelith-atk-3"}]},"spellcasting":{"ability":"int","slots":[{"level":1,"total":4,"used":2},{"level":2,"total":2,"used":0}],"spells":[{"name":"Ray of Frost","level":0,"school":"Evocation","castingTime":"1 action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"prepared":true,"description":"Spell attack; 1d8 Cold damage and −10 feet of Speed.","id":"kaelith-spell-1"},{"name":"Prestidigitation","level":0,"school":"Transmutation","castingTime":"1 action","range":"10 feet","components":"V, S","duration":"Up to 1 hour","concentration":false,"ritual":false,"prepared":true,"description":"Harmless sensory tricks with no mechanical weight.","id":"kaelith-spell-2"},{"name":"Light","level":0,"school":"Evocation","castingTime":"1 action","range":"Touch","components":"V, M","duration":"1 hour","concentration":false,"ritual":false,"prepared":true,"description":"An object sheds Bright Light in a 20-foot radius.","id":"kaelith-spell-3"},{"name":"Magic Missile","level":1,"school":"Evocation","castingTime":"1 action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"prepared":true,"description":"Three darts of 1d4+1 Force damage that always hit.","id":"kaelith-spell-4"},{"name":"Shield","level":1,"school":"Abjuration","castingTime":"1 reaction","range":"Self","components":"V, S","duration":"1 round","concentration":false,"ritual":false,"prepared":true,"description":"+5 AC until your next turn; negates Magic Missile.","id":"kaelith-spell-5"},{"name":"Detect Magic","level":1,"school":"Divination","castingTime":"1 action","range":"Self","components":"V, S","duration":"Conc., 10 min","concentration":true,"ritual":true,"prepared":false,"description":"You sense magical auras within 30 feet.","id":"kaelith-spell-6"},{"name":"Scorching Ray","level":2,"school":"Evocation","castingTime":"1 action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"prepared":true,"description":"Three rays of 2d6 Fire damage; add your spellcasting modifier with Empowered Evocation.","id":"kaelith-spell-7"},{"name":"Levitate","level":2,"school":"Transmutation","castingTime":"1 action","range":"60 feet","components":"V, S, M","duration":"Conc., 10 min","concentration":true,"ritual":false,"prepared":false,"description":"An object or creature floats up to 20 feet upward.","id":"kaelith-spell-8"}],"notes":"Spellbook holds 12 more spells left unprepared. Spellcasting focus: a cut crystal."},"inventory":{"coins":{"pp":0,"gp":42,"ep":0,"sp":15,"cp":0},"items":[{"name":"Spellbook","quantity":1,"weight":3,"attuned":false,"equipped":true,"notes":"Blue leather cover with a brass clasp.","id":"kaelith-item-1"},{"name":"Crystal","quantity":1,"weight":1,"attuned":false,"equipped":true,"notes":"Arcane focus.","id":"kaelith-item-2"},{"name":"Component Pouch","quantity":1,"weight":2,"attuned":false,"equipped":false,"notes":"","id":"kaelith-item-3"},{"name":"Robe","quantity":1,"weight":4,"attuned":false,"equipped":true,"notes":"","id":"kaelith-item-4"},{"name":"Potion of Healing","quantity":2,"weight":0.5,"attuned":false,"equipped":false,"notes":"2d4+2 when drunk (Bonus Action).","id":"kaelith-item-5"},{"name":"Rations","quantity":5,"weight":2,"attuned":false,"equipped":false,"notes":"","id":"kaelith-item-6"},{"name":"Torch","quantity":3,"weight":1,"attuned":false,"equipped":false,"notes":"","id":"kaelith-item-7"}],"notes":""},"features":{"entries":[{"name":"Arcane Recovery","source":"Wizard","description":"Once per day after a Short Rest you recover spell slots with a combined level of up to 2.","usesMax":1,"usesSpent":0,"recharge":"long","id":"kaelith-feat-1"},{"name":"Empowered Evocation","source":"Evoker","description":"You add your Intelligence modifier to the damage of one target of your Evocation cantrips.","usesMax":0,"usesSpent":0,"recharge":"none","id":"kaelith-feat-2"},{"name":"Sculpt Spells","source":"Evoker","description":"When you cast an area Evocation spell, you choose up to 1 + the spell level creatures that automatically succeed on the save and take no damage.","usesMax":0,"usesSpent":0,"recharge":"none","id":"kaelith-feat-3"},{"name":"Fey Ancestry","source":"Elf","description":"Advantage on saves against the Charmed condition; magic can''t put you to sleep.","usesMax":0,"usesSpent":0,"recharge":"none","id":"kaelith-feat-4"}],"languages":["Common","Elvish","Draconic","Deep Speech"],"armor":"None","weapons":"Simple weapons","tools":"Calligrapher''s Supplies"},"journal":{"personality":"Speaks slowly and quotes books nobody else has read.","ideals":"Knowledge that is not shared rots.","bonds":"The library of Vroun burned because of him. He is rebuilding it from memory.","flaws":"Puts an interesting fact ahead of his own safety.","backstory":"Third son of a minor house, he traded the title for an archivist post. In the cellars he found a treatise on evocation that should not exist.","allies":"Master Oriel, of the Crystal College. Fenn the bookseller, who owes him favours.","notes":"Chasing the scattered pages of the Aldaric treatise."}}'::jsonb),
  ('a1000000-0000-4000-8000-000000000002', 'Brann Oldiron', '{"id":"a1000000-0000-4000-8000-000000000002","schemaVersion":4,"createdAt":"2026-01-01T00:00:00.000Z","updatedAt":"2026-01-01T00:00:00.000Z","identity":{"name":"Brann Oldiron","player":"","className":"Barbarian","subclass":"Path of the Berserker","level":3,"species":"Goliath","background":"Soldier","alignment":"Neutral","xp":0,"portrait":"assets/portraits/barbarian.webp","accent":"#c4452f","tagline":"Talks little. Breaks plenty."},"abilities":{"str":17,"dex":13,"con":16,"int":8,"wis":12,"cha":10},"saves":{"str":1,"dex":0,"con":1,"int":0,"wis":0,"cha":0},"skills":{"acrobatics":0,"animalHandling":0,"arcana":0,"athletics":1,"deception":0,"history":0,"insight":0,"intimidation":1,"investigation":0,"medicine":0,"nature":0,"perception":1,"performance":0,"persuasion":0,"religion":0,"sleightOfHand":0,"stealth":0,"survival":1},"combat":{"armorClass":15,"speed":40,"initiativeBonus":0,"hpMax":34,"hpCurrent":26,"hpTemp":0,"hitDieSize":12,"hitDiceTotal":3,"hitDiceSpent":0,"deathSuccesses":0,"deathFailures":0,"heroicInspiration":true,"exhaustion":0,"conditions":[],"attacks":[{"name":"Greataxe","ability":"str","proficient":true,"damage":"1d12","damageType":"Slashing","range":"Melee","mastery":"Cleave","notes":"Two-handed. +2 damage while Raging.","id":"brann-atk-1"},{"name":"Handaxe","ability":"str","proficient":true,"damage":"1d6","damageType":"Slashing","range":"Melee or 20/60 ft.","mastery":"Vex","notes":"","id":"brann-atk-2"},{"name":"Unarmed Strike","ability":"str","proficient":true,"damage":"1","damageType":"Bludgeoning","range":"Melee","mastery":"—","notes":"","id":"brann-atk-3"}]},"spellcasting":{"ability":null,"slots":[],"spells":[],"notes":""},"inventory":{"coins":{"pp":0,"gp":12,"ep":0,"sp":40,"cp":0},"items":[{"name":"Greataxe","quantity":1,"weight":7,"attuned":false,"equipped":true,"notes":"","id":"brann-item-1"},{"name":"Handaxe","quantity":2,"weight":2,"attuned":false,"equipped":false,"notes":"","id":"brann-item-2"},{"name":"Hide Armor","quantity":1,"weight":12,"attuned":false,"equipped":true,"notes":"","id":"brann-item-3"},{"name":"Explorer''s Pack","quantity":1,"weight":55,"attuned":false,"equipped":false,"notes":"","id":"brann-item-4"},{"name":"Hempen Rope (50 feet)","quantity":1,"weight":5,"attuned":false,"equipped":false,"notes":"","id":"brann-item-5"},{"name":"Rations","quantity":10,"weight":2,"attuned":false,"equipped":false,"notes":"","id":"brann-item-6"},{"name":"Regimental medal","quantity":1,"weight":0,"attuned":false,"equipped":false,"notes":"From the Second of Ravenstone. All dead but him.","id":"brann-item-7"}],"notes":""},"features":{"entries":[{"name":"Rage","source":"Barbarian","description":"Bonus Action. Advantage on Strength checks and saves, +2 melee damage, and Resistance to Bludgeoning, Piercing and Slashing damage. Lasts 1 minute.","usesMax":3,"usesSpent":1,"recharge":"long","id":"brann-feat-1"},{"name":"Reckless Attack","source":"Barbarian","description":"When you attack with Strength you roll with Advantage; in exchange, attacks against you have Advantage until your next turn.","usesMax":0,"usesSpent":0,"recharge":"none","id":"brann-feat-2"},{"name":"Danger Sense","source":"Barbarian","description":"Advantage on Dexterity saves against effects you can see (traps, spells).","usesMax":0,"usesSpent":0,"recharge":"none","id":"brann-feat-3"},{"name":"Frenzy","source":"Path of the Berserker","description":"While Raging you can make one extra melee attack as a Bonus Action on each of your turns.","usesMax":0,"usesSpent":0,"recharge":"none","id":"brann-feat-4"},{"name":"Stone''s Endurance","source":"Goliath","description":"As a Reaction you reduce damage taken by 1d12 plus your Constitution modifier. Long Rest.","usesMax":1,"usesSpent":0,"recharge":"long","id":"brann-feat-5"}],"languages":["Common","Giant"],"armor":"Light and Medium armor, Shields","weapons":"Simple and Martial weapons","tools":"A set of bone dice"},"journal":{"personality":"Counts the enemies before the fight. Out loud.","ideals":"A given word is a weight. You do not put it down.","bonds":"The Second of Ravenstone fell at the Kettur pass. He arrived too late.","flaws":"Does not know how to retreat. Never has.","backstory":"He came down from the mountains to work as an escort and ended up in a regiment. When it was wiped out he kept fighting alone until some adventurers picked him up half dead.","allies":"The cleric Sister Maren stitched his side up and never charged him.","notes":"Looking for the officer who ordered the advance at Kettur."}}'::jsonb),
  ('a1000000-0000-4000-8000-000000000003', 'Nyx', '{"id":"a1000000-0000-4000-8000-000000000003","schemaVersion":4,"createdAt":"2026-01-01T00:00:00.000Z","updatedAt":"2026-01-01T00:00:00.000Z","identity":{"name":"Nyx","player":"","className":"Rogue","subclass":"Thief","level":3,"species":"Tiefling","background":"Criminal","alignment":"Neutral","xp":0,"portrait":"assets/portraits/rogue.webp","accent":"#6f78bd","tagline":"You never saw her come in"},"abilities":{"str":10,"dex":17,"con":13,"int":13,"wis":12,"cha":14},"saves":{"str":0,"dex":1,"con":0,"int":1,"wis":0,"cha":0},"skills":{"acrobatics":1,"animalHandling":0,"arcana":0,"athletics":0,"deception":1,"history":0,"insight":0,"intimidation":0,"investigation":1,"medicine":0,"nature":0,"perception":1,"performance":0,"persuasion":0,"religion":0,"sleightOfHand":1,"stealth":1,"survival":0},"combat":{"armorClass":14,"speed":30,"initiativeBonus":0,"hpMax":21,"hpCurrent":21,"hpTemp":0,"hitDieSize":8,"hitDiceTotal":3,"hitDiceSpent":0,"deathSuccesses":0,"deathFailures":0,"heroicInspiration":false,"exhaustion":0,"conditions":[],"attacks":[{"name":"Rapier","ability":"dex","proficient":true,"damage":"1d8","damageType":"Piercing","range":"Melee","mastery":"Vex","notes":"Finesse.","id":"nyx-atk-1"},{"name":"Thrown Dagger","ability":"dex","proficient":true,"damage":"1d4","damageType":"Piercing","range":"Melee or 20/60 ft.","mastery":"Nick","notes":"","id":"nyx-atk-2"},{"name":"Shortbow","ability":"dex","proficient":true,"damage":"1d6","damageType":"Piercing","range":"80/320 ft.","mastery":"Vex","notes":"","id":"nyx-atk-3"}]},"spellcasting":{"ability":null,"slots":[],"spells":[],"notes":"No spellcasting. The Thaumaturgy cantrip comes from her fiendish legacy (1/day)."},"inventory":{"coins":{"pp":3,"gp":60,"ep":0,"sp":0,"cp":0},"items":[{"name":"Rapier","quantity":1,"weight":2,"attuned":false,"equipped":true,"notes":"","id":"nyx-item-1"},{"name":"Dagger","quantity":4,"weight":1,"attuned":false,"equipped":false,"notes":"Two at the belt, one in the boot, one up the sleeve.","id":"nyx-item-2"},{"name":"Shortbow and 20 Arrows","quantity":1,"weight":3,"attuned":false,"equipped":false,"notes":"","id":"nyx-item-3"},{"name":"Leather Armor","quantity":1,"weight":10,"attuned":false,"equipped":true,"notes":"","id":"nyx-item-4"},{"name":"Thieves'' Tools","quantity":1,"weight":1,"attuned":false,"equipped":true,"notes":"Proficient; picks, mirror, files.","id":"nyx-item-5"},{"name":"Disguise Kit","quantity":1,"weight":3,"attuned":false,"equipped":false,"notes":"","id":"nyx-item-6"},{"name":"Silk Rope (50 feet)","quantity":1,"weight":5,"attuned":false,"equipped":false,"notes":"","id":"nyx-item-7"},{"name":"Forged wax seal","quantity":1,"weight":0,"attuned":false,"equipped":false,"notes":"House Verrin. Good for one letter, not two.","id":"nyx-item-8"}],"notes":""},"features":{"entries":[{"name":"Sneak Attack (2d6)","source":"Rogue","description":"Once per turn, +2d6 damage on an attack made with Advantage or with an ally next to the target, using a Finesse or Ranged weapon.","usesMax":0,"usesSpent":0,"recharge":"none","id":"nyx-feat-1"},{"name":"Expertise","source":"Rogue","description":"Double proficiency in Stealth and Sleight of Hand.","usesMax":0,"usesSpent":0,"recharge":"none","id":"nyx-feat-2"},{"name":"Cunning Action","source":"Rogue","description":"Each turn you can Dash, Disengage or Hide as a Bonus Action.","usesMax":0,"usesSpent":0,"recharge":"none","id":"nyx-feat-3"},{"name":"Thieves'' Cant","source":"Rogue","description":"A coded jargon only others who know it can understand.","usesMax":0,"usesSpent":0,"recharge":"none","id":"nyx-feat-4"},{"name":"Fast Hands","source":"Thief","description":"You can use Thieves'' Tools or take the Utilize action as part of the Bonus Action granted by Cunning Action.","usesMax":0,"usesSpent":0,"recharge":"none","id":"nyx-feat-5"},{"name":"Second-Story Work","source":"Thief","description":"You gain a Climb Speed equal to your Speed, and your running jumps go further by a number of feet equal to your Dexterity modifier.","usesMax":0,"usesSpent":0,"recharge":"none","id":"nyx-feat-6"},{"name":"Fiendish Legacy","source":"Tiefling","description":"Resistance to Fire damage. You know Thaumaturgy; at level 3, Hellish Rebuke 1/day.","usesMax":1,"usesSpent":0,"recharge":"long","id":"nyx-feat-7"}],"languages":["Common","Infernal","Deep Speech","Thieves'' Cant"],"armor":"Light armor","weapons":"Simple weapons, Hand Crossbows, Longswords, Rapiers, Shortswords","tools":"Thieves'' Tools, Disguise Kit"},"journal":{"personality":"Answers questions with another question.","ideals":"Locks are an opinion, not a law.","bonds":"She owes her life to an old pickpocket who can no longer work. She sends him money.","flaws":"Cannot walk past a locked safe.","backstory":"She grew up on the rooftops of the Salt Quarter. The guild wanted her; she preferred to freelance and is still paying for it.","allies":"Corvo, the old pickpocket. A customs contact who warns her about raids.","notes":"House Verrin put a price on her head after the necklace business."}}'::jsonb),
  ('a1000000-0000-4000-8000-000000000004', 'Sister Maren', '{"id":"a1000000-0000-4000-8000-000000000004","schemaVersion":4,"createdAt":"2026-01-01T00:00:00.000Z","updatedAt":"2026-01-01T00:00:00.000Z","identity":{"name":"Sister Maren","player":"","className":"Cleric","subclass":"Life Domain","level":3,"species":"Aasimar","background":"Acolyte","alignment":"Neutral","xp":0,"portrait":"assets/portraits/cleric.webp","accent":"#e8c15a","tagline":"The light does not ask permission"},"abilities":{"str":13,"dex":10,"con":14,"int":11,"wis":17,"cha":13},"saves":{"str":0,"dex":0,"con":0,"int":0,"wis":1,"cha":1},"skills":{"acrobatics":0,"animalHandling":0,"arcana":0,"athletics":0,"deception":0,"history":0,"insight":1,"intimidation":0,"investigation":0,"medicine":1,"nature":0,"perception":0,"performance":0,"persuasion":1,"religion":1,"sleightOfHand":0,"stealth":0,"survival":0},"combat":{"armorClass":18,"speed":30,"initiativeBonus":0,"hpMax":24,"hpCurrent":24,"hpTemp":0,"hitDieSize":8,"hitDiceTotal":3,"hitDiceSpent":0,"deathSuccesses":0,"deathFailures":0,"heroicInspiration":false,"exhaustion":0,"conditions":[],"attacks":[{"name":"Mace","ability":"str","proficient":true,"damage":"1d6","damageType":"Bludgeoning","range":"Melee","mastery":"Sap","notes":"","id":"maren-atk-1"},{"name":"Light Crossbow","ability":"dex","proficient":true,"damage":"1d8","damageType":"Piercing","range":"80/320 ft.","mastery":"Slow","notes":"","id":"maren-atk-2"},{"name":"Sacred Flame","ability":"wis","proficient":true,"damage":"2d8","damageType":"Radiant","range":"60 feet","mastery":"—","notes":"Cantrip. Dexterity save, ignores Cover.","id":"maren-atk-3"}]},"spellcasting":{"ability":"wis","slots":[{"level":1,"total":4,"used":1},{"level":2,"total":2,"used":0}],"spells":[{"name":"Sacred Flame","level":0,"school":"Evocation","castingTime":"1 action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"prepared":true,"description":"Dexterity save or 2d8 Radiant damage. Ignores Cover.","id":"maren-spell-1"},{"name":"Thaumaturgy","level":0,"school":"Transmutation","castingTime":"1 action","range":"30 feet","components":"V, S","duration":"Up to 1 min","concentration":false,"ritual":false,"prepared":true,"description":"A booming voice, faint tremors, doors that swing open on their own.","id":"maren-spell-2"},{"name":"Guidance","level":0,"school":"Divination","castingTime":"1 action","range":"Touch","components":"V, S","duration":"Conc., 1 min","concentration":true,"ritual":false,"prepared":true,"description":"+1d4 to one of the target''s ability checks.","id":"maren-spell-3"},{"name":"Cure Wounds","level":1,"school":"Abjuration","castingTime":"1 action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"prepared":true,"description":"Restores 2d8 + spellcasting modifier (with Disciple of Life, +2 more).","id":"maren-spell-4"},{"name":"Bless","level":1,"school":"Enchantment","castingTime":"1 action","range":"Touch","components":"V, S, M","duration":"Conc., 1 min","concentration":true,"ritual":false,"prepared":true,"description":"Up to three creatures add 1d4 to attack rolls and saving throws.","id":"maren-spell-5"},{"name":"Shield of Faith","level":1,"school":"Abjuration","castingTime":"1 Bonus Action","range":"60 feet","components":"V, S","duration":"Conc., 10 min","concentration":true,"ritual":false,"prepared":false,"description":"+2 AC to the target.","id":"maren-spell-6"},{"name":"Spiritual Weapon","level":2,"school":"Evocation","castingTime":"1 Bonus Action","range":"60 feet","components":"V, S","duration":"Conc., 1 min","concentration":true,"ritual":false,"prepared":true,"description":"A spectral weapon: 1d8 + modifier Force damage; you move it and attack as a Bonus Action.","id":"maren-spell-7"},{"name":"Lesser Restoration","level":2,"school":"Abjuration","castingTime":"1 action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"prepared":true,"description":"Ends one disease or one condition: Blinded, Deafened, Paralyzed or Poisoned.","id":"maren-spell-8"},{"name":"Aid","level":2,"school":"Abjuration","castingTime":"1 action","range":"30 feet","components":"V, S","duration":"8 hours","concentration":false,"ritual":false,"prepared":true,"description":"Three creatures raise their Hit Point maximum and current Hit Points by 5. Always prepared (domain).","id":"maren-spell-9"}],"notes":"Prepares 7 spells/day (WIS +3, level 3). Life Domain spells are always prepared."},"inventory":{"coins":{"pp":0,"gp":18,"ep":0,"sp":0,"cp":0},"items":[{"name":"Mace","quantity":1,"weight":4,"attuned":false,"equipped":true,"notes":"","id":"maren-item-1"},{"name":"Shield","quantity":1,"weight":6,"attuned":false,"equipped":true,"notes":"+2 AC (already included).","id":"maren-item-2"},{"name":"Chain Mail","quantity":1,"weight":55,"attuned":false,"equipped":true,"notes":"","id":"maren-item-3"},{"name":"Holy Symbol","quantity":1,"weight":1,"attuned":false,"equipped":true,"notes":"A pewter sun. Spellcasting focus.","id":"maren-item-4"},{"name":"Healer''s Kit","quantity":1,"weight":3,"attuned":false,"equipped":false,"notes":"10 uses. Stabilizes with no roll.","id":"maren-item-5"},{"name":"Holy Water (flask)","quantity":2,"weight":1,"attuned":false,"equipped":false,"notes":"","id":"maren-item-6"},{"name":"Acolyte''s vestments","quantity":1,"weight":4,"attuned":false,"equipped":false,"notes":"","id":"maren-item-7"},{"name":"Rations","quantity":7,"weight":2,"attuned":false,"equipped":false,"notes":"","id":"maren-item-8"}],"notes":""},"features":{"entries":[{"name":"Channel Divinity","source":"Cleric","description":"Two uses per rest. Fuels Turn Undead and Preserve Life.","usesMax":2,"usesSpent":0,"recharge":"short","id":"maren-feat-1"},{"name":"Turn Undead","source":"Cleric","description":"Each Undead within 30 feet must succeed on a Wisdom save or flee for 1 minute.","usesMax":0,"usesSpent":0,"recharge":"none","id":"maren-feat-2"},{"name":"Preserve Life","source":"Life Domain","description":"Spend Channel Divinity to split 5 × your level in Hit Points among creatures within 30 feet, up to half their maximum.","usesMax":0,"usesSpent":0,"recharge":"none","id":"maren-feat-3"},{"name":"Disciple of Life","source":"Life Domain","description":"Your level 1+ healing spells restore 2 + the spell level extra Hit Points.","usesMax":0,"usesSpent":0,"recharge":"none","id":"maren-feat-4"},{"name":"Celestial Revelation","source":"Aasimar","description":"As a Bonus Action, transform 1/Long Rest: wings or radiant burst, plus extra Radiant damage.","usesMax":1,"usesSpent":0,"recharge":"long","id":"maren-feat-5"}],"languages":["Common","Celestial"],"armor":"Light and Medium armor, Shields","weapons":"Simple weapons","tools":"None"},"journal":{"personality":"Listens all the way through before answering. Always.","ideals":"Nobody is left behind over what it costs to save them.","bonds":"The temple of Elyon raised her. She will go back when this is over.","flaws":"Holds herself responsible for wounds she could not have prevented.","backstory":"Left as a child on temple steps, she grew up among the sick and the dying. The celestial mark showed at fifteen, and with it the certainty that she was not meant to stay home.","allies":"Brother Tobin, who writes to her. Brann, who owes her a side.","notes":"A fever is running through the Green River villages and it does not answer to magic."}}'::jsonb),
